const makeCatalogDrink = ({ id, name, terms, category, emoji, calories, sugar, serving, tips }) => ({
  id,
  name,
  searchTerms: terms,
  category,
  grade: sugar <= 5 ? 'A' : sugar <= 12 ? 'B' : sugar <= 25 ? 'C' : sugar <= 35 ? 'D' : 'E',
  gradeColor: sugar <= 5 ? '#10b981' : sugar <= 12 ? '#84cc16' : sugar <= 25 ? '#eab308' : sugar <= 35 ? '#f97316' : '#ef4444',
  calories,
  sugar,
  sugarPercent: Math.round((sugar / 50) * 100),
  fat: 0,
  protein: 0,
  status: sugar <= 5 ? 'Rendah Gula' : sugar <= 25 ? 'Perhatikan Porsi' : 'Tinggi Gula',
  emoji,
  source: 'Perkiraan per sajian; cek label kemasan',
  servingDescription: serving,
  tips,
  nutritionList: [
    { label: 'Kalori', value: `${calories} kkal`, desc: calories > 200 ? 'Tinggi' : calories > 100 ? 'Sedang' : 'Rendah' },
    { label: 'Gula', value: `${sugar} gram`, desc: `${Math.round((sugar / 50) * 100)}% batas harian` },
    { label: 'Lemak', value: '0 gram', desc: 'Bervariasi' },
    { label: 'Protein', value: '0 gram', desc: 'Bervariasi' }
  ]
});

