export const findVerifiedDrink = (query) => {
  const q = String(query).toLowerCase().trim();
  if (!q) return null;

  return VERIFIED_DRINKS.find((d) =>
    d.id === q ||
    d.name.toLowerCase().includes(q) ||
    d.searchTerms.some((t) => t.toLowerCase().includes(q) || q.includes(t.toLowerCase()))
  ) || null;
};
